# Converts a duration such as "1h30m" or "45s" to seconds.
# Supported units are days (d), hours (h), minutes (m), and seconds (s).
# Raises ArgumentError for empty or malformed durations.
def duration_in_seconds(duration)
  unless duration.is_a?(String) && duration.match?(/\A(?:\d+[dhms])+\z/)
    raise ArgumentError, "invalid duration: #{duration.inspect}"
  end

  units = { "d" => 86_400, "h" => 3_600, "m" => 60, "s" => 1 }
  duration.scan(/(\d+)([dhms])/).sum { |amount, unit| amount.to_i * units.fetch(unit) }
end
